import { createSignal } from "solid-js";

const KEY = "bookshelf:favorites";
const [favs, setFavs] = createSignal<string[]>([]);
let loaded = false;

export function loadFavorites() {
  if (loaded) return;
  loaded = true;
  try {
    setFavs(JSON.parse(localStorage.getItem(KEY) ?? "[]"));
  } catch {}
}

export const isFavorite = (slug: string) => favs().includes(slug);

export function toggleFavorite(slug: string) {
  const next = isFavorite(slug) ? favs().filter(s => s !== slug) : [...favs(), slug];
  setFavs(next);
  localStorage.setItem(KEY, JSON.stringify(next));
}
