import { Title } from "@solidjs/meta";
import { action, useSubmission } from "@solidjs/router";
import { Show, createSignal } from "solid-js";
import { validate, type Errors } from "~/lib/contact";

type Result = { errors?: Errors; values: { name: string; email: string; message: string }; ok?: boolean };

const read = (f: FormData) => ({
  name: String(f.get("name") ?? "").trim(),
  email: String(f.get("email") ?? "").trim(),
  message: String(f.get("message") ?? "").trim(),
});

const send = action(async (form: FormData): Promise<Result> => {
  "use server";
  const values = read(form);
  const errors = validate(values);
  if (Object.keys(errors).length) return { errors, values };
  return { ok: true, values };
}, "contact-send");

export default function Contact() {
  const sub = useSubmission(send);
  const [local, setLocal] = createSignal<Errors | null>(null);
  const result = () => sub.result as Result | undefined;
  const errors = (): Errors => local() ?? result()?.errors ?? {};
  const v = (k: keyof Errors) => result()?.values[k] ?? "";
  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={result()?.ok && !local()}>
        <p>Thanks, {result()!.values.name}! Your message has been sent.</p>
      </Show>
      <form
        action={send}
        method="post"
        novalidate
        on:submit={e => {
          const errs = validate(read(new FormData(e.currentTarget)));
          if (Object.keys(errs).length) {
            e.preventDefault();
            e.stopPropagation();
            setLocal(errs);
          } else setLocal(null);
        }}
      >
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={v("name")} />
          <Show when={errors().name}><span>{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={v("email")} />
          <Show when={errors().email}><span>{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message">{v("message")}</textarea>
          <Show when={errors().message}><span>{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
