import { createMiddleware } from "@solidjs/start/middleware";
import { getRequestEvent } from "solid-js/web";
import { readForm, process } from "~/lib/contact";

// Without JavaScript the form posts to /contact itself; the page renders with the outcome.
export default createMiddleware([
  async (event, next) => {
    const url = new URL(event.req.url);
    if (event.req.method === "POST" && url.pathname === "/contact") {
      const form = await event.req.clone().formData();
      const re = getRequestEvent();
      if (re) re.locals.contact = process(readForm(form));
    }
    return next();
  },
]);
