import { Title } from "@solidjs/meta";
import { createAsync } from "@solidjs/router";
import { Show, createSignal } from "solid-js";
import { getRequestEvent } from "solid-js/web";
import { process, readForm, validate, type Errors, type Result } from "~/lib/contact";

async function postedResult(): Promise<Result | null> {
  "use server";
  return getRequestEvent()?.locals.contact ?? null;
}

async function send(form: FormData): Promise<Result> {
  "use server";
  return process(readForm(form));
}

export default function Contact() {
  const posted = createAsync(() => postedResult());
  const [result, setResult] = createSignal<Result | null>(null);
  const current = () => result() ?? posted() ?? null;
  const errors = (): Errors => current()?.errors ?? {};
  const v = (k: keyof Errors) => current()?.values[k] ?? "";
  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={current()?.ok}>
        <p>Thanks, {current()!.values.name}! Your message has been sent.</p>
      </Show>
      <form
        action="/contact"
        method="post"
        novalidate
        on:submit={async e => {
          e.preventDefault();
          const form = new FormData(e.currentTarget);
          const local = process(readForm(form));
          setResult(local.ok ? await send(form) : local);
        }}
      >
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={v("name")} />
          <Show when={errors().name}><span>{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={v("email")} />
          <Show when={errors().email}><span>{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message">{v("message")}</textarea>
          <Show when={errors().message}><span>{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
